        let mut rt = ObscuraJsRuntime::new();
        rt.set_dom(parse_html(
            r#"<html style="margin:0"><body style="margin:0">
                <div style="width:80px;height:60px;background:#1769aa"></div>
            </body></html>"#,
        ));
